#!/bin/sh
# Ignite Sentinel plugin: find Python 3.10+ and run it with these arguments (IMP-290).
# Generated by `python -m sentinel.adapters --plugin`; do not edit by hand.
#
# Many Windows laptops have Python installed but neither `python` nor `py` on PATH,
# or only the Microsoft Store alias (WindowsApps), which is not Python. Order:
#   1. $SENTINEL_PYTHON
#   2. python3, python, py -3 on PATH (Store aliases skipped)
#   3. the usual Windows install folders under %LOCALAPPDATA% and %ProgramFiles%
# Each candidate must report Python 3.10 or newer before it is used.

usable() {
  "$@" -c 'import sys; sys.exit(0 if sys.version_info >= (3, 10) else 1)' >/dev/null 2>&1
}

if [ -n "${SENTINEL_PYTHON:-}" ] && usable "$SENTINEL_PYTHON"; then
  exec "$SENTINEL_PYTHON" "$@"
fi

for name in python3 python; do
  found=$(command -v "$name" 2>/dev/null) || continue
  case "$found" in *WindowsApps*) continue ;; esac
  if usable "$found"; then exec "$found" "$@"; fi
done

if command -v py >/dev/null 2>&1 && usable py -3; then
  exec py -3 "$@"
fi

posix_path() {
  if command -v cygpath >/dev/null 2>&1; then cygpath -u "$1"; else printf '%s\n' "$1" | sed 's#\\#/#g'; fi
}

for base in "${LOCALAPPDATA:-}" "${ProgramFiles:-}" "${PROGRAMFILES:-}"; do
  [ -n "$base" ] || continue
  base=$(posix_path "$base")
  for candidate in "$base"/Programs/Python/Python3*/python.exe "$base"/Python/pythoncore-3*/python.exe "$base"/Python3*/python.exe; do
    [ -f "$candidate" ] || continue
    if usable "$candidate"; then exec "$candidate" "$@"; fi
  done
done

echo "Ignite Sentinel needs Python 3.10 or newer and could not find it." >&2
echo "Install it from https://www.python.org/downloads/ (tick \"Add python.exe to PATH\")," >&2
echo "or set SENTINEL_PYTHON to the full path of python.exe." >&2
exit 127
